files.bin/mcp-echo.ps1:
$ErrorActionPreference = 'Stop'
[Console]::Error.WriteLine('echo server starting')
$in = [Console]::In
while ($null -ne ($line = $in.ReadLine())) {
    $message = $line | ConvertFrom-Json
    if ($null -eq $message.method -or $null -eq $message.id) { continue }
    $answer = @{ jsonrpc = '2.0'; id = $message.id }
    switch ($message.method) {
        'initialize' { $answer.result = @{ protocolVersion = '2025-11-25'; capabilities = @{ tools = @{} }; serverInfo = @{ name = 'echo'; version = '1.0.0' } } }
        'tools/list' { $answer.result = @{ tools = @(@{ name = 'echo'; description = 'Repeat the text it is given.'; inputSchema = @{ type = 'object'; properties = @{ text = @{ type = 'string' } } } }) } }
        'tools/call' { $answer.result = @{ content = @(@{ type = 'text'; text = 'echo from Windows: ' + $message.params.arguments.text }) } }
        'ping' { $answer.result = @{} }
        default { $answer.error = @{ code = -32601; message = 'Method not found: ' + $message.method } }
    }
    [Console]::Out.WriteLine(($answer | ConvertTo-Json -Depth 10 -Compress))
    [Console]::Out.Flush()
}
